-- =====================================================================
--  NOTE EN FOURCHETTE + ORDRE DES ETALONS
--
--  OU  : Supabase, projet "pipeline de correction" (xgdaibekjmtffvkwvcge)
--  QUOI: SQL Editor > New query > coller UN BLOC > Run
--
--  Deux corrections validees sur HLP le 2026-07-28, reportees ici sur SES,
--  SVT et HGGSP. Le francais n'est pas touche : il est en production et
--  prouve, on n'y change rien sans raison.
--
--  1. NOTE EN FOURCHETTE (demande de Cindy).
--     Le dossier eleve n'affiche plus une note seche mais une estimation
--     encadree ("entre 12 et 14"). Le moteur continue de produire un nombre
--     exact dans corrections.result_json.note_finale : le CRM en a besoin
--     pour les moyennes et le report de note. Seul l'AFFICHAGE change, donc
--     seuls les dossier_templates sont modifies. Aucun code touche.
--     Regle : demi-largeur = 5 % du bareme (1 point sur 20), doublee quand
--     human_review_required vaut true. Verifie sur HLP : une copie a 6/20
--     passee en corrected_review s'affiche "4 - 8 / 20".
--
--  2. ORDRE DES ETALONS.
--     Sur une dissertation HGGSP notee 7,75, le modele renvoyait
--     lower_or_equal_id = l'etalon a 9 et upper_or_equal_id = celui a 5,
--     soit l'inverse. La consigne d'ordre ajoutee aux system_prompt corrige
--     le probleme : verifie sur HLP (N05 -> N09 pour une copie a 6).
--
--  Idempotent : chaque update reecrit le texte complet, et le script qui a
--  genere ce fichier n'ajoute rien si le marqueur est deja present.
--  Tout le texte accentue passe par convert_from(decode(...,'hex'),'UTF8').
-- =====================================================================


-- =====================================================================
--  BLOC A - ORDRE DES ETALONS (8 grilles)
-- =====================================================================

begin;

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'HGGSP_DISSERTATION_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'HGGSP_ETUDE_CRITIQUE_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_DISSERTATION_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_EC1_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_EC2_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_EC3_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SVT_EXERCICE1_V1';

update public.rubrics set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SVT_EXERCICE2_V1';

commit;


-- =====================================================================
--  BLOC B - NOTE EN FOURCHETTE (8 gabarits de dossier)
-- =====================================================================

begin;

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'HGGSP_DOSSIER_DISSERTATION_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'HGGSP_DOSSIER_ETUDE_CRITIQUE_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_DOSSIER_DISSERTATION_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_DOSSIER_EC1_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_DOSSIER_EC2_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SES_DOSSIER_EC3_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SVT_DOSSIER_EX1_ELEVE_V1';

update public.dossier_templates set system_prompt = convert_from(decode('','hex'),'UTF8') where id = 'SVT_DOSSIER_EX2_ELEVE_V1';

commit;


-- =====================================================================
--  BLOC C - VERIFICATION
--  Attendu : ordre_etalons = true pour toutes les grilles hors francais,
--  fourchette = true pour tous les gabarits hors francais.
-- =====================================================================

select 'grille' as objet, id, matiere,
       (system_prompt like '%benchmark_comparison.lower_or_equal_id doit designer%') as ordre_etalons
from public.rubrics where matiere <> 'francais'
union all
select 'gabarit', id, matiere,
       (system_prompt like '%LA NOTE S'AFFICHE EN FOURCHETTE%')
from public.dossier_templates where matiere <> 'francais'
order by 3, 1, 2;
